using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace App.Entities;

/// <summary>A document of the "orders" collection.</summary>
[BsonIgnoreExtraElements]
public class Order
{
    [BsonId]
    [BsonRepresentation(BsonType.ObjectId)]
    public string Id { get; set; } = null!;

    [BsonElement("number")]
    public double Number { get; set; }

    [BsonElement("year")]
    public double Year { get; set; }

    [BsonElement("customer")]
    [BsonRepresentation(BsonType.ObjectId)]
    public string Customer { get; set; } = null!;

    [BsonElement("lines")]
    public List<Order.LineDocument> Lines { get; set; } = null!;

    [BsonElement("notes")]
    [BsonIgnoreIfNull]
    public List<Order.NoteDocument>? Notes { get; set; }

    [BsonElement("placedAt")]
    [BsonIgnoreIfNull]
    public DateTime? PlacedAt { get; set; }

    /// <summary>Gives an identifier to the documents of its lists that have none: MongoDB numbers only whole documents.</summary>
    public void IdentifyItems()
    {
        foreach (var item in Lines ?? []) item.Id ??= ObjectId.GenerateNewId().ToString();
        foreach (var item in Notes ?? []) item.Id ??= ObjectId.GenerateNewId().ToString();
    }

    /// <summary>A nested document: it is stored with the one that holds it.</summary>
    [BsonIgnoreExtraElements]
    public class LineDocument
    {
        [BsonId]
        [BsonRepresentation(BsonType.ObjectId)]
        [BsonIgnoreIfNull]
        public string? Id { get; set; }

        [BsonElement("product")]
        [BsonRepresentation(BsonType.ObjectId)]
        public string Product { get; set; } = null!;

        [BsonElement("quantity")]
        public double Quantity { get; set; }

        [BsonElement("price")]
        [BsonRepresentation(BsonType.Decimal128)]
        public decimal Price { get; set; }

        [BsonElement("status")]
        [BsonIgnoreIfNull]
        public string? Status { get; set; }
    }

    /// <summary>A nested document: it is stored with the one that holds it.</summary>
    [BsonIgnoreExtraElements]
    public class NoteDocument
    {
        [BsonId]
        [BsonRepresentation(BsonType.ObjectId)]
        [BsonIgnoreIfNull]
        public string? Id { get; set; }

        [BsonElement("text")]
        [BsonIgnoreIfNull]
        public string? Text { get; set; }

        [BsonElement("at")]
        [BsonIgnoreIfNull]
        public DateTime? At { get; set; }
    }
}

