/// <summary>Keeps countries rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryCountryRepository : ICountryRepository
{
    private readonly Dictionary<string, Country> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Country row) => [row.DocumentId];

    private static string KeyText(Country row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Country> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Country?> FindByDocumentIdAsync(string documentId)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.DocumentId, documentId)));
    }

    public Task<Page<Country>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Country>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<Country?> FindByIdAsync(double id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Country> InsertAsync(Country entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Country> UpdateAsync(Country entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Country entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
