using System.Runtime.CompilerServices;
using App;
using App.Common;
using App.Entities;
using App.Errors;
using MongoDB.Bson;
using MongoDB.Driver;

namespace App.Repositories;

/// <summary>Keeps countries documents in the database, through the MongoDB driver. Every write is stored at once.</summary>
public class MongoCountryRepository(Db db) : ICountryRepository
{
    private const string Collection = "countries";

    /// <summary>The document each entity was read from: a change writes only the fields that differ</summary>
    private static readonly ConditionalWeakTable<Country, BsonDocument> Read = [];

    /// <summary>The fields a change may write</summary>
    private static readonly string[] Fields = ["id", "name"];

    public async Task<Country?> FindByDocumentIdAsync(string documentId)
    {
        var found = await db.Find(Collection, Builders<Country>.Filter.Eq(row => row.DocumentId, documentId)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<Page<Country>> ListAsync(int offset, int limit)
    {
        var items = (await db.Find(Collection, Builders<Country>.Filter.Empty).Sort(Builders<Country>.Sort.Ascending(row => row.DocumentId)).Skip(offset).Limit(limit).ToListAsync()).Select(Loaded).ToList();
        return new Page<Country>(items, await db.CountAsync(Collection, Builders<Country>.Filter.Empty), offset, limit);
    }

    public async Task<Country?> FindByIdAsync(double id)
    {
        var found = await db.Find(Collection, Builders<Country>.Filter.Eq(row => row.Id, id)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<Country> InsertAsync(Country entity)
    {
        await db.InsertAsync("Country", Collection, entity);
        return Loaded(entity);
    }

    public async Task<Country> UpdateAsync(Country entity)
    {
        var now = entity.ToBsonDocument();
        var changes = Documents.Changes(Read.TryGetValue(entity, out var before) ? before : null, now, Fields);
        if (changes.ElementCount > 0) await db.UpdateAsync<Country>("Country", Collection, new BsonDocument("_id", now["_id"]), changes);
        return Loaded(entity);
    }

    public async Task DeleteAsync(Country entity)
    {
        await db.DeleteAsync("Country", Collection, Builders<Country>.Filter.Eq(row => row.DocumentId, entity.DocumentId));
    }

    /// <summary>The same entity, with what it is stored as kept to tell its changes.</summary>
    private static Country Loaded(Country entity)
    {
        Read.AddOrUpdate(entity, entity.ToBsonDocument());
        return entity;
    }
}

