using System.Runtime.CompilerServices;
using App;
using App.Common;
using App.Entities;
using App.Errors;
using MongoDB.Bson;
using MongoDB.Driver;

namespace App.Repositories;

/// <summary>Keeps customers documents in the database, through the MongoDB driver. Every write is stored at once.</summary>
public class MongoCustomerRepository(Db db) : ICustomerRepository
{
    private const string Collection = "customers";

    /// <summary>The document each entity was read from: a change writes only the fields that differ</summary>
    private static readonly ConditionalWeakTable<Customer, BsonDocument> Read = [];

    /// <summary>The fields a change may write</summary>
    private static readonly string[] Fields = ["email", "name", "passwordHash", "active", "level", "address", "tags", "preferences", "extra", "deletedAt"];

    public async Task<Customer?> FindByIdAsync(string id)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var found = await db.Find(Collection, Builders<Customer>.Filter.And(Builders<Customer>.Filter.Eq(row => row.Id, id), Builders<Customer>.Filter.Eq(row => row.DeletedAt, null))).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<Page<Customer>> ListAsync(int offset, int limit)
    {
        var items = (await db.Find(Collection, Builders<Customer>.Filter.Eq(row => row.DeletedAt, null)).Sort(Builders<Customer>.Sort.Ascending(row => row.Id)).Skip(offset).Limit(limit).ToListAsync()).Select(Loaded).ToList();
        return new Page<Customer>(items, await db.CountAsync(Collection, Builders<Customer>.Filter.Eq(row => row.DeletedAt, null)), offset, limit);
    }

    public async Task<Customer?> FindByEmailAsync(string email)
    {
        var found = await db.Find(Collection, Builders<Customer>.Filter.And(Builders<Customer>.Filter.Eq(row => row.Email, email), Builders<Customer>.Filter.Eq(row => row.DeletedAt, null))).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<Customer> InsertAsync(Customer entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        entity.Active ??= true;
        entity.Level ??= "basic";
        entity.CreatedAt ??= DateTime.UtcNow;
        entity.UpdatedAt ??= DateTime.UtcNow;
        await db.InsertAsync("Customer", Collection, entity);
        return Loaded(entity);
    }

    public async Task<Customer> UpdateAsync(Customer entity)
    {
        entity.UpdatedAt = DateTime.UtcNow;
        var now = entity.ToBsonDocument();
        var changes = Documents.Changes(Read.TryGetValue(entity, out var before) ? before : null, now, Fields);
        if (changes.ElementCount > 0)
        {
            if (!changes.Contains("$set")) changes["$set"] = new BsonDocument();
            changes["$set"]["updatedAt"] = now["updatedAt"];
        }
        if (changes.ElementCount > 0) await db.UpdateAsync<Customer>("Customer", Collection, new BsonDocument("_id", now["_id"]), changes);
        return Loaded(entity);
    }

    public async Task DeleteAsync(Customer entity)
    {
        await db.DeleteAsync("Customer", Collection, Builders<Customer>.Filter.Eq(row => row.Id, entity.Id));
    }

    public async Task<Customer?> AddTagAsync(string id, string tag)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var change = new BsonDocument { ["$push"] = new BsonDocument("tags", BsonValue.Create(tag)), ["$set"] = new BsonDocument { ["updatedAt"] = DateTime.UtcNow } };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id), ["deletedAt"] = BsonNull.Value };
        var changed = await db.ChangeAsync<Customer>("Customer", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    public async Task<Customer?> RemoveTagAsync(string id, string tag)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var change = new BsonDocument { ["$pull"] = new BsonDocument("tags", BsonValue.Create(tag)), ["$set"] = new BsonDocument { ["updatedAt"] = DateTime.UtcNow } };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id), ["deletedAt"] = BsonNull.Value };
        var changed = await db.ChangeAsync<Customer>("Customer", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    /// <summary>The same entity, with what it is stored as kept to tell its changes.</summary>
    private static Customer Loaded(Customer entity)
    {
        Read.AddOrUpdate(entity, entity.ToBsonDocument());
        return entity;
    }
}

