    private static readonly string[] Fields = ["number", "year", "customer", "lines", "notes"];

    public async Task<Order?> FindByIdAsync(string id)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var found = await db.Find(Collection, Builders<Order>.Filter.Eq(row => row.Id, id)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<Page<Order>> ListAsync(int offset, int limit)
    {
        var items = (await db.Find(Collection, Builders<Order>.Filter.Empty).Sort(Builders<Order>.Sort.Ascending(row => row.Id)).Skip(offset).Limit(limit).ToListAsync()).Select(Loaded).ToList();
        return new Page<Order>(items, await db.CountAsync(Collection, Builders<Order>.Filter.Empty), offset, limit);
    }

    public async Task<Order?> FindByYearAndNumberAsync(double year, double number)
    {
        var found = await db.Find(Collection, Builders<Order>.Filter.And(Builders<Order>.Filter.Eq(row => row.Year, year), Builders<Order>.Filter.Eq(row => row.Number, number))).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<List<Order>> ListByCustomerAsync(string customer)
    {
        if (!ObjectId.TryParse(customer, out _)) return [];
        return (await db.Find(Collection, Builders<Order>.Filter.Eq(row => row.Customer, customer)).Sort(Builders<Order>.Sort.Ascending(row => row.Id)).ToListAsync()).Select(Loaded).ToList();
    }

    public async Task<Order> InsertAsync(Order entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        entity.PlacedAt ??= DateTime.UtcNow;
        entity.IdentifyItems();
        await db.InsertAsync("Order", Collection, entity);
        return Loaded(entity);
    }

    public async Task<Order> UpdateAsync(Order entity)
    {
        entity.IdentifyItems();
        var now = entity.ToBsonDocument();
        var changes = Documents.Changes(Read.TryGetValue(entity, out var before) ? before : null, now, Fields);
        if (changes.ElementCount > 0) await db.UpdateAsync<Order>("Order", Collection, new BsonDocument("_id", now["_id"]), changes);
        return Loaded(entity);
    }

    public async Task DeleteAsync(Order entity)
    {
        await db.DeleteAsync("Order", Collection, Builders<Order>.Filter.Eq(row => row.Id, entity.Id));
    }

    public async Task<Order?> AddLineAsync(string id, Order.LineDocument line)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        line.Id ??= ObjectId.GenerateNewId().ToString();
        var change = new BsonDocument { ["$push"] = new BsonDocument("lines", line.ToBsonDocument()) };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id) };
        var changed = await db.ChangeAsync<Order>("Order", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    public async Task<Order?> RemoveLineAsync(string id, string lineId)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        if (!ObjectId.TryParse(lineId, out _)) return null;
        var change = new BsonDocument { ["$pull"] = new BsonDocument("lines", new BsonDocument("_id", new ObjectId(lineId))) };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id) };
        var changed = await db.ChangeAsync<Order>("Order", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    public async Task<Order?> AddNoteAsync(string id, Order.NoteDocument note)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        note.Id ??= ObjectId.GenerateNewId().ToString();
        var change = new BsonDocument { ["$push"] = new BsonDocument("notes", note.ToBsonDocument()) };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id) };
        var changed = await db.ChangeAsync<Order>("Order", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    public async Task<Order?> RemoveNoteAsync(string id, string noteId)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        if (!ObjectId.TryParse(noteId, out _)) return null;
        var change = new BsonDocument { ["$pull"] = new BsonDocument("notes", new BsonDocument("_id", new ObjectId(noteId))) };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id) };
        var changed = await db.ChangeAsync<Order>("Order", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    /// <summary>The same entity, with what it is stored as kept to tell its changes.</summary>
    private static Order Loaded(Order entity)
    {
        Read.AddOrUpdate(entity, entity.ToBsonDocument());
        return entity;
    }
}

