namespace App.Repositories;

/// <summary>Keeps products documents in the database, through the MongoDB driver. Every write is stored at once.</summary>
public class MongoProductRepository(Db db) : IProductRepository
{
    private const string Collection = "products";

    /// <summary>The document each entity was read from: a change writes only the fields that differ</summary>
    private static readonly ConditionalWeakTable<Product, BsonDocument> Read = [];

    /// <summary>The fields a change may write</summary>
    private static readonly string[] Fields = ["sku", "title", "price", "stock", "reference", "picture", "related"];

    public async Task<Product?> FindByIdAsync(string id)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var found = await db.Find(Collection, Builders<Product>.Filter.Eq(row => row.Id, id)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<Page<Product>> ListAsync(int offset, int limit)
    {
        var items = (await db.Find(Collection, Builders<Product>.Filter.Empty).Sort(Builders<Product>.Sort.Ascending(row => row.Id)).Skip(offset).Limit(limit).ToListAsync()).Select(Loaded).ToList();
        return new Page<Product>(items, await db.CountAsync(Collection, Builders<Product>.Filter.Empty), offset, limit);
    }

    public async Task<Product?> FindBySkuAsync(string sku)
    {
        var found = await db.Find(Collection, Builders<Product>.Filter.Eq(row => row.Sku, sku)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<List<Product>> FindAllByTitleAsync(string title)
    {
        return (await db.Find(Collection, Builders<Product>.Filter.Eq(row => row.Title, title)).Sort(Builders<Product>.Sort.Ascending(row => row.Id)).ToListAsync()).Select(Loaded).ToList();
    }

    public async Task<Product> InsertAsync(Product entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        entity.Stock ??= 0.0;
        await db.InsertAsync("Product", Collection, entity);
        return Loaded(entity);
    }

    public async Task<Product> UpdateAsync(Product entity)
    {
        var now = entity.ToBsonDocument();
        var changes = Documents.Changes(Read.TryGetValue(entity, out var before) ? before : null, now, Fields);
        if (changes.ElementCount > 0) await db.UpdateAsync<Product>("Product", Collection, new BsonDocument("_id", now["_id"]), changes);
        return Loaded(entity);
    }

    public async Task DeleteAsync(Product entity)
    {
        await db.DeleteAsync("Product", Collection, Builders<Product>.Filter.Eq(row => row.Id, entity.Id));
    }

    public async Task<Product?> AddRelatedAsync(string id, string related)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var change = new BsonDocument { ["$push"] = new BsonDocument("related", new ObjectId(related)) };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id) };
        var changed = await db.ChangeAsync<Product>("Product", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    public async Task<Product?> RemoveRelatedAsync(string id, string related)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var change = new BsonDocument { ["$pull"] = new BsonDocument("related", new ObjectId(related)) };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id) };
        var changed = await db.ChangeAsync<Product>("Product", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    /// <summary>The same entity, with what it is stored as kept to tell its changes.</summary>
    private static Product Loaded(Product entity)
    {
        Read.AddOrUpdate(entity, entity.ToBsonDocument());
        return entity;
    }
}

