namespace App.Tests;

/// <summary>Rows for the tests: valid values for every column, and the rows they point to.</summary>
internal static class Factories
{
    /// <summary>A valid Customer that is not stored yet; n makes its unique values differ.</summary>
    public static Customer NewCustomer(int n)
    {
        var entity = new Customer();
        entity.Email = $"email-{n}";
        entity.Name = $"name-{n}";
        entity.PasswordHash = $"passwordhash-{n}";
        entity.Active = true;
        entity.Level = "basic";
        entity.Address = NewCustomerAddress(n);
        entity.Tags = [];
        entity.Preferences = NewCustomerPreferences(n);
        entity.Extra = new MongoDB.Bson.BsonDocument("n", n);
        entity.UpdatedAt = new DateTime(2026, 1, n % 28 + 1, 12, 0, 0, DateTimeKind.Utc);
        return entity;
    }

    /// <summary>A stored Customer.</summary>
    public static async Task<Customer> AddCustomerAsync(IUnitOfWork uow, int n)
    {
        var entity = NewCustomer(n);
        return await uow.Customers.InsertAsync(entity);
    }

    /// <summary>A valid Customer.AddressDocument.</summary>
    public static Customer.AddressDocument NewCustomerAddress(int n) => new()
    {
        Street = $"street-{n}",
        City = $"city-{n}",
        ZipCode = $"zipcode-{n}",
        Location = NewCustomerAddressLocation(n),
    };

