    public static Customer.PreferencesDocument NewCustomerPreferences(int n) => new()
    {
        Theme = $"theme-{n}",
        Newsletter = true,
    };

    /// <summary>A valid Product that is not stored yet; n makes its unique values differ.</summary>
    public static Product NewProduct(int n)
    {
        var entity = new Product();
        entity.Sku = $"sku-{n}";
        entity.Title = $"title-{n}";
        entity.Price = (n % 10000) + 0.50m;
        entity.Stock = n + 0.5;
        entity.Reference = Guid.Parse($"00000000-0000-4000-8000-{n:D12}");
        entity.Picture = new byte[] { (byte)n };
        entity.Related = [];
        return entity;
    }

    /// <summary>A stored Product.</summary>
    public static async Task<Product> AddProductAsync(IUnitOfWork uow, int n)
    {
        var entity = NewProduct(n);
        return await uow.Products.InsertAsync(entity);
    }

