    {
        var entity = new Order();
        entity.Number = n + 0.5;
        entity.Year = n + 0.5;
        entity.Lines = [NewOrderLine(n)];
        entity.Notes = [NewOrderNote(n)];
        return entity;
    }

    /// <summary>A stored Order, with the rows it points to.</summary>
    public static async Task<Order> AddOrderAsync(IUnitOfWork uow, int n)
    {
        var parent0 = await AddCustomerAsync(uow, n);
        var entity = NewOrder(n);
        entity.Customer = parent0.Id;
        return await uow.Orders.InsertAsync(entity);
    }

    /// <summary>A valid Order.LineDocument.</summary>
    public static Order.LineDocument NewOrderLine(int n) => new()
    {
